def pdf_styles():
    font=r"C:\Windows\Fonts\msyh.ttc"
    bold=r"C:\Windows\Fonts\msyhbd.ttc"
    pdfmetrics.registerFont(TTFont("CN",font)); pdfmetrics.registerFont(TTFont("CNB",bold))
    s=getSampleStyleSheet()
    return {
      "title":ParagraphStyle("title",fontName="CNB",fontSize=20,leading=28,textColor=colors.HexColor("#17365D"),alignment=TA_CENTER,spaceAfter=16),
      "h1":ParagraphStyle("h1",fontName="CNB",fontSize=14,leading=20,textColor=colors.HexColor("#17365D"),spaceBefore=10,spaceAfter=7),
      "body":ParagraphStyle("body",fontName="CN",fontSize=9.5,leading=16,textColor=colors.HexColor("#263238"),spaceAfter=6),
      "small":ParagraphStyle("small",fontName="CN",fontSize=8,leading=12,textColor=colors.HexColor("#555555"))}

def build_pdf(path,title,code,steps):
    st=pdf_styles(); doc=SimpleDocTemplate(str(path),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=17*mm,bottomMargin=17*mm,title=title,author="OpenAI Codex")
    story=[Paragraph("华辰银行",st["title"]),Paragraph(title+"（V1.0）",st["title"]),Paragraph(f"文件编号：{code}　生效日期：2026-08-25　适用范围：零售客户经理及协同岗位",st["body"]),Spacer(1,8),Paragraph("适用说明",st["h1"]),Paragraph("本材料用于内部培训、业务演练与知识检索验证，具体业务办理以本行现行制度、产品文件及系统结果为准。",st["body"]),PageBreak()]
    story += [Paragraph("一、目的与原则",st["h1"]),Paragraph("统一客户经理受理、核验、风险提示、升级和留痕动作，确保客户获得清晰、一致、可追溯的服务。执行中坚持客户本人真实意愿、适当性、最小必要、审慎合规和信息保护原则。",st["body"]),Paragraph("二、职责分工",st["h1"])]
    role_data=[[Paragraph("角色",st["small"]),Paragraph("主要职责",st["small"])],[Paragraph("客户经理",st["small"]),Paragraph("需求识别、材料受理、风险提示、系统录入和客户沟通。",st["small"])],[Paragraph("网点主管",st["small"]),Paragraph("异常复核、授权审批、投诉和高风险事件协调。",st["small"])],[Paragraph("专业/合规岗位",st["small"]),Paragraph("专业审查、风险判断、制度解释和升级处置。",st["small"])]]
    t=Table(role_data,colWidths=[36*mm,130*mm]); t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#17365D")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONTNAME",(0,0),(-1,-1),"CN"),("GRID",(0,0),(-1,-1),0.4,colors.HexColor("#B8C4CE")),("VALIGN",(0,0),(-1,-1),"TOP"),("PADDING",(0,0),(-1,-1),6)])); story += [t,PageBreak(),Paragraph("三、标准流程",st["h1"])]
    pdata=[[Paragraph("步骤",st["small"]),Paragraph("责任人",st["small"]),Paragraph("动作与交付物",st["small"]),Paragraph("控制点",st["small"])]]
    for i,x in enumerate(steps,1): pdata.append([Paragraph(str(i),st["small"]),Paragraph("客户经理/协同岗",st["small"]),Paragraph(x+"；结果录入业务系统并保存必要凭证。",st["small"]),Paragraph("不得代客操作、隐瞒风险或绕过系统控制。",st["small"])])
    t=Table(pdata,colWidths=[12*mm,31*mm,78*mm,45*mm],repeatRows=1); t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#2F75B5")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONTNAME",(0,0),(-1,-1),"CN"),("GRID",(0,0),(-1,-1),0.35,colors.HexColor("#B8C4CE")),("VALIGN",(0,0),(-1,-1),"TOP"),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#EEF5FB")]),("PADDING",(0,0),(-1,-1),5)])); story += [t,PageBreak(),Paragraph("四、材料与留痕清单",st["h1"])]
    for x in ["客户身份、联系方式及授权依据","客户需求、交易背景和风险评估记录","所使用的审批版产品或服务材料","系统校验、双录、签署及交易凭证","异常说明、升级工单和客户沟通记录"]: story.append(Paragraph("• "+x,st["body"]))
    story += [Paragraph("五、异常与升级",st["h1"])]
    adata=[[Paragraph("异常情形",st["small"]),Paragraph("首要动作",st["small"]),Paragraph("升级对象",st["small"])],[Paragraph("身份、授权或真实意愿存疑",st["small"]),Paragraph("暂停办理并保全原始材料",st["small"]),Paragraph("网点主管/运营",st["small"])],[Paragraph("疑似欺诈、胁迫或资金来源异常",st["small"]),Paragraph("停止交易，不泄露监测规则",st["small"]),Paragraph("反欺诈/反洗钱专岗",st["small"])],[Paragraph("客户投诉、舆情或重大损失风险",st["small"]),Paragraph("先受理、编号并明确反馈时间",st["small"]),Paragraph("消保/合规负责人",st["small"])],[Paragraph("资料误发或隐私泄露",st["small"]),Paragraph("立即止损、报告和补救",st["small"]),Paragraph("信息安全/合规",st["small"])]]
    t=Table(adata,colWidths=[60*mm,64*mm,42*mm]); t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#17365D")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONTNAME",(0,0),(-1,-1),"CN"),("GRID",(0,0),(-1,-1),0.4,colors.HexColor("#B8C4CE")),("VALIGN",(0,0),(-1,-1),"TOP"),("PADDING",(0,0),(-1,-1),5)])); story += [t,PageBreak(),Paragraph("六、客户沟通口径",st["h1"])]
    for x in ["我先核实您的实际需求和账户状态，再给您准确的办理路径。","相关条件以系统、合同和产品文件为准，我不能提前承诺结果。","为了保护您的资金和信息安全，这一步需要由您本人确认。","目前存在需要进一步核实的情况，我会提交主管或专业岗位处理并告知进展。"]: story.append(Paragraph("“"+x+"”",st["body"]))
    story += [Paragraph("七、办理前自检",st["h1"])]
    for x in ["身份与授权是否已核验","需求、用途和资金来源是否清晰","风险与费用是否充分说明","是否由客户本人完成关键操作","材料、录音和系统记录是否完整","异常是否已按时升级"]: story.append(Paragraph("□ "+x,st["body"]))
    story += [Spacer(1,12),Paragraph("版本记录：V1.0 / 2026-08-25 / 首次发布 / 内部培训",st["small"])]
    doc.build(story)

